"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["2259"],{18618(e){e.exports=JSON.parse('{"id":"FIN-917","slug":"delta","term":"Delta","also_known_as":[],"difficulty":"Intermediate","definition":"Delta is a measure of how much an option\'s price is expected to change when the price of the underlying asset changes by one unit.","explanation":["Delta ranges from 0 to 1 for call options and from 0 to \u22121 for put options. A call option with a delta of 0.6 is expected to rise by about 0.60 when the underlying share price rises by 1. A put option with a delta of \u22120.4 is expected to rise by about 0.40 when the share price falls by 1.","Delta depends on how likely the option is to finish in the money. Options that are deep in the money have deltas close to 1 or \u22121, moving almost one-for-one with the share. Options far out of the money have deltas close to zero, barely responding to small price changes. At-the-money options typically have deltas around 0.5 or \u22120.5.","Delta is also used as a hedge ratio. For example, a trader who has sold 10 call option contracts, each covering 100 shares, with a delta of 0.6, can hedge by buying about 600 shares. This delta hedge protects against small price movements.","Delta changes as the share price moves, as time passes and as volatility changes. The rate at which delta changes is measured by gamma, which is why delta hedges need to be adjusted regularly."],"note":"","total":1500,"prev":{"slug":"delinquency","term":"Delinquency"},"next":{"slug":"delta-hedging","term":"Delta Hedging"}}')}}]);